/* From Uiverse.io by shadowmurphy  - Tags: simple, material design, neumorphism, skeuomorphism, input */
.__UIV_SCOPE__ .search-bar {
  width: 200px;
  height: 35px;
  border-radius: 5px;
  outline: none;
  border: 1px solid #303030;
  border-bottom: 2px solid #9a9a9a;
  padding-left: 10px;
  padding-right: 10px;
  background-color: #2d2d2d;
  color: white;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .search-bar::placeholder {
  color: #9a9a9a;
}

.__UIV_SCOPE__ .search-bar:hover {
  background-color: #313131;
}

.__UIV_SCOPE__ .search-bar:active,
.__UIV_SCOPE__ .search-bar:focus {
  background-color: #1e1f20;
  border: 1px solid #2d2d2d;
  border-bottom: 2px solid #4cc2ff;
}
